--
-- 表的结构 `admin_permission`
--

CREATE TABLE `admin_permission` (
  `id` bigint(20) UNSIGNED NOT NULL COMMENT 'ID',
  `parent_id` bigint(20) UNSIGNED NOT NULL DEFAULT '0' COMMENT '父ID 0是顶级',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '控制名称',
  `path` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '控制器URL',
  `component` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'vue前台页面',
  `is_menu` tinyint(1) UNSIGNED NOT NULL DEFAULT '10' COMMENT '作为菜单显示,10是,20不是',
  `icon` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '小图标名称',
  `create_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `sort` tinyint(1) UNSIGNED DEFAULT '255' COMMENT '排序越小越往前',
  `hidden` tinyint(1) UNSIGNED NOT NULL DEFAULT '10' COMMENT '10显示20不显示'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='管理员权限表';

