--
-- 表的结构 `request_log`
--

CREATE TABLE `request_log` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `create_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `method` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '请求方式',
  `ip` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '请求ip',
  `url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '请求url',
  `params` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '请求参数',
  `header` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '请求header',
  `data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '杩斿洖鐨勬暟鎹?涓嶅寘鍚玠ata',
  `return_at` datetime DEFAULT NULL COMMENT '返回结果的时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='请求日志表';

